// #Sireum

package greenhouse_ventilation.runtimemonitor

import org.sireum._
import greenhouse_ventilation._

// Do not edit this file as it will be overwritten if HAMR codegen is rerun

object GumboXDispatcher {
  def checkContract(observationKind: ObservationKind.Type, preContainer: Option[art.DataContent], postContainer: Option[art.DataContent]): B = {
    observationKind match {
      case greenhouse_ventilation.runtimemonitor.ObservationKind.Greenhouse_Ventilation_Root_Instance_control_process_ventilation_decision_postInit =>
        // checking the post-state values of ventilation_decision's initialise entrypoint is not required
        return T
      case greenhouse_ventilation.runtimemonitor.ObservationKind.Greenhouse_Ventilation_Root_Instance_control_process_ventilation_decision_preCompute =>
        // checking the pre-state values of ventilation_decision's compute entrypoint is not required
        return T
      case greenhouse_ventilation.runtimemonitor.ObservationKind.Greenhouse_Ventilation_Root_Instance_control_process_ventilation_decision_postCompute =>
        // checking the post-state values of ventilation_decision's compute entrypoint is not required
        return T

      case _ => halt("Infeasible")
    }
  }

  def genTestSuite(testCases: ISZ[(Z, ISZ[ST])]): Unit = {
    val tq = "\"\"\""

    val testRoot = Os.path(".") / "src" / "test" / "bridge"

    val Ventilation_Decision_i_control_process_ventilation_decision_id = Arch.Greenhouse_Ventilation_Root_Instance_control_process_ventilation_decision.id

    def genUniqueSuiteName(path: Os.Path, prefix: String): String = {
      var i = 0
      while(true) {
        val cand = path / s"${prefix}_${i}.scala"
        if (!cand.exists) {
          return s"${prefix}_${i}"
        }
        i = i + 1
      }
      halt("Infeasible")
    }

    for (p <- testCases) {
      art.Art.BridgeId.fromZ(p._1) match {
        case Ventilation_Decision_i_control_process_ventilation_decision_id =>
          val prefix = "Ventilation_Decision_i_control_process_ventilation_decision_RM_TestSuite"
          val path = testRoot /+ ISZ("greenhouse_ventilation","Greenhouse_Ventilation")
          val suiteName = genUniqueSuiteName(path, prefix)

          val testSuite =
            st"""package greenhouse_ventilation.Greenhouse_Ventilation
                |
                |import org.sireum._
                |import greenhouse_ventilation.Greenhouse_Ventilation._
                |
                |class ${suiteName} extends Ventilation_Decision_i_control_process_ventilation_decision_GumboX_TestHarness_ScalaTest {
                |  val verbose: B = T
                |
                |  ${p._2}
                |}"""
          val filename = path / s"${suiteName}.scala"
          filename.writeOver(testSuite.render)
          println(s"Wrote: ${filename.toUri}")
        case x => halt(s"Infeasible bridge id: $x")
      }
    }
  }

  def genTestCase(observationKind: ObservationKind.Type, preContainer: Option[String], postContainer: Option[String], testNameSuffix: Option[String]): ST = {
    val tq = "\"\"\""
    val suffix: String =
      if (testNameSuffix.nonEmpty) testNameSuffix.get
      else ""

    observationKind match {

      case _ => return st"// TODO ${observationKind}"
    }
  }

  def getUpdates(bridge_id: art.Art.BridgeId, observationKind: ObservationKind.Type, container: art.DataContent): Map[String, String] = {
    observationKind match {
      case greenhouse_ventilation.runtimemonitor.ObservationKind.Greenhouse_Ventilation_Root_Instance_control_process_ventilation_decision_postInit =>
        var updates: Map[String, String] = Map.empty
        val postContainer = container.asInstanceOf[greenhouse_ventilation.Greenhouse_Ventilation.Ventilation_Decision_i_control_process_ventilation_decision_PostState_Container_PS]
        updates = updates + s"${bridge_id}_Out_fan_command" ~> postContainer.api_fan_command.string
        updates = updates + s"${bridge_id}_Out_sensor_fault" ~> postContainer.api_sensor_fault.string
        return updates
      case greenhouse_ventilation.runtimemonitor.ObservationKind.Greenhouse_Ventilation_Root_Instance_control_process_ventilation_decision_preCompute =>
        var updates: Map[String, String] = Map.empty
        val preContainer = container.asInstanceOf[greenhouse_ventilation.Greenhouse_Ventilation.Ventilation_Decision_i_control_process_ventilation_decision_PreState_Container_PS]
        updates = updates + s"${bridge_id}_In_temperature" ~> preContainer.api_temperature.string
        updates = updates + s"${bridge_id}_In_validity" ~> preContainer.api_validity.string
        updates = updates + s"${bridge_id}_In_upper_limit" ~> preContainer.api_upper_limit.string
        return updates
      case greenhouse_ventilation.runtimemonitor.ObservationKind.Greenhouse_Ventilation_Root_Instance_control_process_ventilation_decision_postCompute =>
        var updates: Map[String, String] = Map.empty
        val postContainer = container.asInstanceOf[greenhouse_ventilation.Greenhouse_Ventilation.Ventilation_Decision_i_control_process_ventilation_decision_PostState_Container_PS]
        updates = updates + s"${bridge_id}_Out_fan_command" ~> postContainer.api_fan_command.string
        updates = updates + s"${bridge_id}_Out_sensor_fault" ~> postContainer.api_sensor_fault.string
        return updates
      case _ => return Map.empty
    }
  }
}